import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    M = data[1]
    T = data[2:2 + M]

    n = N
    for t in T:
        n -= n // t

    S = n if n < 10000 else 10000

    rev_d = [t - 1 for t in reversed(T)]

    out = []
    append = out.append

    for k in range(1, S + 1):
        p = k
        for d in rev_d:
            if d == 1:
                p = (p << 1) - 1
            elif d < p:
                p += (p - 1) // d
        append(str(p))

    sys.stdout.write("\n".join(out) + "\n")

if __name__ == "__main__":
    main()
